import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

async function queryRows<T>(ctx: AssertionContext, sql: string): Promise<T[]> {
  const result = await ctx.clickhouse.query({ query: sql, format: "JSONEachRow" });
  return (await (result as any).json()) as T[];
}

async function fetchJson(url: string): Promise<any> {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}

export async function all_thirty_events_ingested(ctx: AssertionContext): Promise<AssertionResult> {
  const rows = await queryRows<{ n: number }>(
    ctx,
    "SELECT count() AS n FROM analytics.product_events",
  );
  const count = Number(rows[0]?.n ?? 0);
  const passed = count === 30;
  return {
    passed,
    message: passed ? "All 30 events ingested." : `Expected 30 events, got ${count}.`,
    details: { count },
  };
}

export async function event_types_preserved(ctx: AssertionContext): Promise<AssertionResult> {
  const rows = await queryRows<{ t: string }>(
    ctx,
    "SELECT DISTINCT event_type AS t FROM analytics.product_events ORDER BY t",
  );
  const types = rows.map((r) => r.t).sort();
  const expected = ["cart", "purchase", "view"];
  const passed = JSON.stringify(types) === JSON.stringify(expected);
  return {
    passed,
    message: passed ? "Event types preserved." : `Expected ${JSON.stringify(expected)}, got ${JSON.stringify(types)}.`,
    details: { types },
  };
}

export async function top_products_returns_data(): Promise<AssertionResult> {
  const data = await fetchJson("http://localhost:3000/api/top-products");
  const passed = Array.isArray(data) && data.length > 0;
  return {
    passed,
    message: passed ? "Top products API returns data." : "Top products API returned empty or invalid data.",
    details: { length: Array.isArray(data) ? data.length : 0 },
  };
}

export async function funnel_has_three_steps(): Promise<AssertionResult> {
  const data = await fetchJson("http://localhost:3000/api/funnel");
  if (!Array.isArray(data) || data.length < 3) {
    return {
      passed: false,
      message: "Funnel API returned insufficient data.",
      details: { length: Array.isArray(data) ? data.length : 0 },
    };
  }
  const steps = data.map((d: any) => (d.step ?? d.event_type ?? "").toLowerCase());
  const passed = steps.includes("view") && steps.includes("cart") && steps.includes("purchase");
  return {
    passed,
    message: passed ? "Funnel has view, cart, and purchase steps." : `Missing steps. Got: ${JSON.stringify([...new Set(steps)])}.`,
    details: { steps: [...new Set(steps)] },
  };
}

export async function funnel_counts_are_monotonic(): Promise<AssertionResult> {
  const data = await fetchJson("http://localhost:3000/api/funnel");
  if (!Array.isArray(data) || data.length < 3) {
    return {
      passed: false,
      message: "Funnel API returned insufficient data.",
      details: { length: Array.isArray(data) ? data.length : 0 },
    };
  }

  const byStep: Record<string, number> = {};
  for (const row of data) {
    const step = (row.step ?? row.event_type ?? "").toLowerCase();
    byStep[step] = Number(row.unique_users ?? row.users ?? row.count ?? 0);
  }

  const views = byStep["view"] ?? 0;
  const carts = byStep["cart"] ?? 0;
  const purchases = byStep["purchase"] ?? 0;
  const passed = views >= carts && carts >= purchases && purchases > 0;
  return {
    passed,
    message: passed ? "Funnel counts are monotonic." : `Monotonic check failed: views=${views}, carts=${carts}, purchases=${purchases}.`,
    details: { views, carts, purchases },
  };
}

export async function hourly_returns_data(): Promise<AssertionResult> {
  const data = await fetchJson("http://localhost:3000/api/hourly");
  const passed = Array.isArray(data) && data.length > 0;
  return {
    passed,
    message: passed ? "Hourly API returns data." : "Hourly API returned empty or invalid data.",
    details: { length: Array.isArray(data) ? data.length : 0 },
  };
}

export async function revenue_checksum(ctx: AssertionContext): Promise<AssertionResult> {
  const pgResult = await ctx.pg.query(
    "SELECT COALESCE(SUM((properties->>'price')::numeric), 0) AS total FROM raw.product_events WHERE event_type = 'purchase'",
  );
  const pgTotal = Number(pgResult.rows[0]?.total ?? 0);

  const data = await fetchJson("http://localhost:3000/api/top-products");
  if (!Array.isArray(data)) {
    return {
      passed: false,
      message: "Top products API returned invalid data.",
      details: { pgTotal },
    };
  }

  const apiTotal = data.reduce(
    (sum: number, row: any) => sum + Number(row.revenue ?? 0),
    0,
  );
  const passed = Math.abs(pgTotal - apiTotal) < 0.01;
  return {
    passed,
    message: passed ? "Revenue checksum matches." : `Revenue mismatch: pg=${pgTotal}, api=${apiTotal}.`,
    details: { pgTotal, apiTotal },
  };
}

import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

async function queryRows<T>(ctx: AssertionContext, sql: string): Promise<T[]> {
  const result = await ctx.clickhouse.query({ query: sql, format: "JSONEachRow" });
  return (await (result as any).json()) as T[];
}

export async function events_table_exists(ctx: AssertionContext): Promise<AssertionResult> {
  const rows = await queryRows<{ n: number }>(
    ctx,
    "SELECT count() AS n FROM system.tables WHERE database = 'analytics' AND name = 'product_events'",
  );
  const count = Number(rows[0]?.n ?? 0);
  const passed = count === 1;
  return {
    passed,
    message: passed ? "Events table exists." : `Expected 1 table, got ${count}.`,
    details: { count },
  };
}

export async function events_table_has_rows(ctx: AssertionContext): Promise<AssertionResult> {
  const rows = await queryRows<{ n: number }>(
    ctx,
    "SELECT count() AS n FROM analytics.product_events",
  );
  const count = Number(rows[0]?.n ?? 0);
  const passed = count > 0;
  return {
    passed,
    message: passed ? "Events table has rows." : "Events table is empty.",
    details: { count },
  };
}

export async function api_server_responds(ctx: AssertionContext): Promise<AssertionResult> {
  try {
    const response = await fetch("http://localhost:3000/api/top-products");
    const passed = response.ok;
    return {
      passed,
      message: passed ? "API server responds." : `API returned status ${response.status}.`,
      details: { status: response.status },
    };
  } catch (e) {
    return {
      passed: false,
      message: "API server did not respond.",
      details: { error: e instanceof Error ? e.message : String(e) },
    };
  }
}

import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

import { hasReadmeOrDocs, scanWorkspaceForHardcodedConnections } from "../../_shared/assertion-helpers";

export async function connection_env_vars_available(ctx: AssertionContext): Promise<AssertionResult> {
  const hasPostgres = Boolean(ctx.env("POSTGRES_URL"));
  const hasClickHouse = Boolean(ctx.env("CLICKHOUSE_URL"));
  const passed = hasPostgres && hasClickHouse;
  return {
    passed,
    message: passed ? "Connection env vars available." : "Missing POSTGRES_URL or CLICKHOUSE_URL.",
    details: { hasPostgres, hasClickHouse },
  };
}

export async function api_does_not_hardcode_credentials(): Promise<AssertionResult> {
  const { readFileSync, readdirSync } = await import("node:fs");
  const { join } = await import("node:path");

  const suspectPatterns = ["password", "secret", "5432", "9000"];
  const dirs = ["/workspace"];
  let foundFile = "";

  outer: for (const dir of dirs) {
    let files: string[];
    try {
      files = readdirSync(dir);
    } catch {
      continue;
    }
    for (const file of files) {
      if (!file.endsWith(".js") && !file.endsWith(".ts") && !file.endsWith(".py")) continue;
      try {
        const content = readFileSync(join(dir, file), "utf8");
        for (const pattern of suspectPatterns) {
          if (content.includes(pattern) && !content.includes("process.env") && !content.includes("os.environ")) {
            foundFile = join(dir, file);
            break outer;
          }
        }
      } catch {
        continue;
      }
    }
  }
  const passed = !foundFile;
  return {
    passed,
    message: passed ? "No hardcoded credentials found." : `Suspect pattern found in ${foundFile}.`,
    details: foundFile ? { foundFile } : undefined,
  };
}

export async function no_hardcoded_connection_strings(): Promise<AssertionResult> {
  return scanWorkspaceForHardcodedConnections();
}

import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

async function fetchJson(url: string): Promise<any> {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}

export async function api_returns_valid_json_content_type(): Promise<AssertionResult> {
  const res = await fetch("http://localhost:3000/api/top-products");
  const ct = res.headers.get("content-type") ?? "";
  const passed = ct.includes("application/json");
  return {
    passed,
    message: passed ? "API returns valid JSON content-type." : `Content-Type: ${ct}.`,
    details: { contentType: ct },
  };
}

export async function api_handles_unknown_route(): Promise<AssertionResult> {
  const res = await fetch("http://localhost:3000/api/nonexistent");
  const passed = res.status === 404 || res.status === 400;
  return {
    passed,
    message: passed ? "API handles unknown route." : `Unexpected status ${res.status} for unknown route.`,
    details: { status: res.status },
  };
}

export async function no_duplicate_products_in_top(): Promise<AssertionResult> {
  const data = await fetchJson("http://localhost:3000/api/top-products");
  if (!Array.isArray(data)) {
    return {
      passed: false,
      message: "Top products API returned invalid data.",
    };
  }
  const ids = data.map((r: any) => r.product_id ?? r.id ?? "");
  const passed = new Set(ids).size === ids.length;
  return {
    passed,
    message: passed ? "No duplicate products in top." : `Found ${ids.length - new Set(ids).size} duplicates.`,
    details: { uniqueCount: new Set(ids).size, totalCount: ids.length },
  };
}

import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

export async function top_products_under_200ms(): Promise<AssertionResult> {
  const start = Date.now();
  await fetch("http://localhost:3000/api/top-products");
  const elapsed = Date.now() - start;
  const passed = elapsed < 200;
  return {
    passed,
    message: passed ? "Top products under 200ms." : `Top products took ${elapsed}ms.`,
    details: { elapsedMs: elapsed },
  };
}

export async function funnel_under_200ms(): Promise<AssertionResult> {
  const start = Date.now();
