/**
 * One-shot: create ClickHouse analytics objects and load from Postgres.
 * Uses env: POSTGRES_URL, CLICKHOUSE_URL (see process.env below).
 */
import pg from "pg";
import { chExec, chExecLines } from "./clickhouse-http.mjs";

const pgUrl = process.env.POSTGRES_URL;
if (!pgUrl) throw new Error("POSTGRES_URL is required");

async function main() {
  await chExec(`CREATE DATABASE IF NOT EXISTS analytics`);

  await chExec(`DROP TABLE IF EXISTS analytics.mv_top_products`);
  await chExec(`DROP TABLE IF EXISTS analytics.top_products`);
  await chExec(`DROP TABLE IF EXISTS analytics.mv_hourly`);
  await chExec(`DROP TABLE IF EXISTS analytics.hourly_activity`);
  await chExec(`DROP VIEW IF EXISTS analytics.conversion_funnel`);
  await chExec(`DROP TABLE IF EXISTS analytics.product_events`);

  await chExec(`
    CREATE TABLE analytics.product_events (
      event_id String,
      event_ts DateTime64(3, 'UTC'),
      user_id String,
      product_id String,
      event_type LowCardinality(String),
      properties String
    )
    ENGINE = MergeTree()
    ORDER BY (event_type, product_id, event_ts)
  `);

  await chExec(`
    CREATE TABLE analytics.top_products (
      product_id String,
      view_count UInt64,
      cart_count UInt64,
      purchase_count UInt64,
      revenue Float64
    )
    ENGINE = SummingMergeTree()
    ORDER BY product_id
  `);

  await chExec(`
    CREATE MATERIALIZED VIEW analytics.mv_top_products TO analytics.top_products AS
    SELECT
      product_id,
      countIf(event_type = 'view') AS view_count,
      countIf(event_type = 'cart') AS cart_count,
      countIf(event_type = 'purchase') AS purchase_count,
      sumIf(toFloat64(JSONExtractFloat(properties, 'price')), event_type = 'purchase') AS revenue
    FROM analytics.product_events
    GROUP BY product_id
  `);

  await chExec(`
    CREATE TABLE analytics.hourly_activity (
      hour DateTime,
      event_type LowCardinality(String),
      event_count UInt64
    )
    ENGINE = SummingMergeTree()
    ORDER BY (hour, event_type)
  `);

  await chExec(`
    CREATE MATERIALIZED VIEW analytics.mv_hourly TO analytics.hourly_activity AS
    SELECT
      toStartOfHour(event_ts) AS hour,
      event_type,
      toUInt64(count()) AS event_count
    FROM analytics.product_events
    GROUP BY hour, event_type
  `);

  await chExec(`
    CREATE VIEW analytics.conversion_funnel AS
    SELECT
      event_type AS step,
      toUInt64(uniqExact(user_id)) AS unique_users,
      toUInt64(count()) AS total_events
    FROM analytics.product_events
    GROUP BY event_type
  `);

  const pool = new pg.Pool({ connectionString: pgUrl });
  const { rows } = await pool.query(`
    SELECT event_id, event_ts, user_id, product_id, event_type, properties
    FROM raw.product_events
    ORDER BY event_ts
  `);
  await pool.end();

  if (!rows.length) {
    console.warn("No rows in raw.product_events; skipping insert.");
    return;
  }

  const lines = rows.map((r) => {
    const props =
      r.properties == null
        ? "{}"
        : typeof r.properties === "string"
          ? r.properties
          : JSON.stringify(r.properties);
    const ts = r.event_ts instanceof Date ? r.event_ts.toISOString() : String(r.event_ts);
    const chTs = ts.replace("T", " ").replace(/\.\d{3}Z$/, "").replace("Z", "");
    return JSON.stringify({
      event_id: r.event_id,
      event_ts: chTs,
      user_id: r.user_id,
      product_id: r.product_id,
      event_type: r.event_type,
      properties: props,
    });
  });

  await chExecLines(
    `INSERT INTO analytics.product_events FORMAT JSONEachRow`,
    lines,
  );

  console.log(`Loaded ${rows.length} events into ClickHouse.`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

