const chBase = process.env.CLICKHOUSE_URL;
if (!chBase) throw new Error("CLICKHOUSE_URL is required");

function chUrl(extra = "") {
  const u = new URL(chBase.endsWith("/") ? chBase.slice(0, -1) : chBase);
  if (extra) u.pathname = (u.pathname || "") + extra;
  return u.toString();
}

export async function chExec(sql) {
  const res = await fetch(chUrl(), {
    method: "POST",
    body: sql,
    headers: { "Content-Type": "text/plain" },
  });
  if (!res.ok) {
    const t = await res.text();
    throw new Error(`ClickHouse error ${res.status}: ${t.slice(0, 500)}`);
  }
}

export async function chExecLines(sqlPrefix, lines) {
  const body = sqlPrefix + "\n" + lines.join("\n") + "\n";
  const res = await fetch(chUrl(), {
    method: "POST",
    body,
    headers: { "Content-Type": "text/plain" },
  });
  if (!res.ok) {
    const t = await res.text();
    throw new Error(`ClickHouse insert error ${res.status}: ${t.slice(0, 500)}`);
  }
}

export async function chQueryJsonEachRow(sql) {
  const res = await fetch(chUrl(), {
    method: "POST",
    body: `${sql}\nFORMAT JSONEachRow\n`,
    headers: { "Content-Type": "text/plain" },
  });
  if (!res.ok) {
    const t = await res.text();
    throw new Error(`ClickHouse query error ${res.status}: ${t.slice(0, 500)}`);
  }
  const text = await res.text();
  if (!text.trim()) return [];
  return text
    .trim()
    .split("\n")
    .filter(Boolean)
    .map((line) => JSON.parse(line));
}

