import http from "node:http";
import { spawn } from "node:child_process";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { chQueryJsonEachRow } from "./clickhouse-http.mjs";

const __dirname = dirname(fileURLToPath(import.meta.url));

function json(res, status, body) {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    "Content-Type": "application/json; charset=utf-8",
    "Content-Length": Buffer.byteLength(payload),
  });
  res.end(payload);
}

async function runSetupOnce() {
  await new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [join(__dirname, "setup.mjs")], {
      stdio: "inherit",
      env: process.env,
    });
    child.on("error", reject);
    child.on("exit", (code) =>
      code === 0 ? resolve() : reject(new Error(`setup.mjs exited ${code}`)),
    );
  });
}

async function handleTopProducts() {
  return chQueryJsonEachRow(`
    SELECT
      product_id,
      sum(view_count) AS view_count,
      sum(cart_count) AS cart_count,
      sum(purchase_count) AS purchase_count,
      sum(revenue) AS revenue
    FROM analytics.top_products
    GROUP BY product_id
    ORDER BY purchase_count DESC
    LIMIT 10
  `);
}

async function handleFunnel() {
  return chQueryJsonEachRow(`
    SELECT step, unique_users, total_events
    FROM analytics.conversion_funnel
    ORDER BY
      multiIf(step = 'view', 1, step = 'cart', 2, step = 'purchase', 3, 4),
      step
  `);
}

async function handleHourly() {
  return chQueryJsonEachRow(`
    SELECT
      hour,
      event_type,
      sum(event_count) AS event_count
    FROM analytics.hourly_activity
    GROUP BY hour, event_type
    ORDER BY hour, event_type
  `);
}

const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url || "/", `http://${req.headers.host}`);
    if (req.method !== "GET") {
      json(res, 405, { error: "Method not allowed" });
      return;
    }
    if (url.pathname === "/api/top-products") {
      json(res, 200, await handleTopProducts());
      return;
    }
    if (url.pathname === "/api/funnel") {
      json(res, 200, await handleFunnel());
      return;
    }
    if (url.pathname === "/api/hourly") {
      json(res, 200, await handleHourly());
      return;
    }
    json(res, 404, { error: "Not found" });
  } catch (e) {
    console.error(e);
    json(res, 500, { error: "Internal server error" });
  }
});

await runSetupOnce();

server.listen(3000, "0.0.0.0", () => {
  console.log("Listening on http://0.0.0.0:3000");
});

